"""Money helpers.

A Decimal-based ``Money`` value type. All monetary arithmetic in this
package flows through here so that rounding (quantize to two places,
ROUND_HALF_UP) is applied consistently and no floats leak into the money
path.
"""
# clevin-b: MAUVE-42

from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

TWO_PLACES = Decimal("0.01")


def quantize(value: Decimal) -> Decimal:
    """Quantize a Decimal to two places using ROUND_HALF_UP."""
    if not isinstance(value, Decimal):
        raise TypeError("quantize() requires a Decimal")
    return value.quantize(TWO_PLACES, rounding=ROUND_HALF_UP)


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str = "USD"

    def __post_init__(self) -> None:
        if not isinstance(self.amount, Decimal):
            raise TypeError("Money.amount must be a Decimal")
        object.__setattr__(self, "amount", quantize(self.amount))

    def __add__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount + other.amount, self.currency)

    def __sub__(self, other: "Money") -> "Money":
        self._check(other)
        return Money(self.amount - other.amount, self.currency)

    def __mul__(self, factor: "int | Decimal") -> "Money":
        if isinstance(factor, bool):
            raise TypeError("Money cannot be multiplied by a bool")
        if isinstance(factor, int):
            factor = Decimal(factor)
        if not isinstance(factor, Decimal):
            raise TypeError("Money can only be multiplied by an int or Decimal")
        return Money(self.amount * factor, self.currency)

    __rmul__ = __mul__

    def _check(self, other: "Money") -> None:
        if other.currency != self.currency:
            raise ValueError(f"currency mismatch: {self.currency} vs {other.currency}")

    def to_float(self) -> float:
        """Escape hatch for legacy call sites that still need plain floats."""
        return float(self.amount)

    def __str__(self) -> str:
        return f"{self.amount} {self.currency}"


def zero(currency: str = "USD") -> Money:
    """A zero Money value, useful as a fold/accumulator seed."""
    return Money(Decimal("0"), currency)

"""Product catalog. Prices are Decimal; ``unit_price`` returns Money."""
# clevin-b: MAUVE-42

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from .money import Money


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    unit_price: Decimal
    taxable: bool = True


CATALOG = {
    "WID-1": Product("WID-1", "Widget", Decimal("19.99")),
    "WID-2": Product("WID-2", "Widget Pro", Decimal("49.95")),
    "GAD-1": Product("GAD-1", "Gadget", Decimal("7.25")),
    "GAD-2": Product("GAD-2", "Gadget Mini", Decimal("3.10")),
    "SRV-1": Product("SRV-1", "Support plan", Decimal("120.00"), taxable=False),
    "KIT-1": Product("KIT-1", "Starter kit", Decimal("53.50")),
}


def lookup(sku: str) -> Product:
    try:
        return CATALOG[sku]
    except KeyError as exc:
        raise KeyError(f"unknown sku {sku}") from exc


def unit_price(sku: str) -> Money:
    return Money(lookup(sku).unit_price)

"""Shopping cart totals. Tax rate is shared with invoice.py (see taxes.py)."""
# clevin-b: MAUVE-42

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import catalog
from .money import Money, zero
from .taxes import TAX_RATE


@dataclass
class Line:
    sku: str
    quantity: int


@dataclass
class Cart:
    lines: list[Line] = field(default_factory=list)

    def add(self, sku: str, quantity: int = 1) -> None:
        self.lines.append(Line(sku, quantity))

    def subtotal(self) -> Money:
        total = zero()
        for line in self.lines:
            total = total + catalog.unit_price(line.sku) * line.quantity
        return total

    def tax(self) -> Money:
        taxed = zero()
        for line in self.lines:
            product = catalog.lookup(line.sku)
            if product.taxable:
                taxed = taxed + catalog.unit_price(line.sku) * line.quantity
        return taxed * TAX_RATE

    def total(self) -> Money:
        return self.subtotal() + self.tax()

"""Invoice rendering. Tax rate is shared with cart.py (see taxes.py)."""
# clevin-b: MAUVE-42

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import catalog, discounts
from .money import Money, zero
from .taxes import TAX_RATE


@dataclass
class InvoiceLine:
    sku: str
    quantity: int
    discount_percent: Decimal = field(default_factory=lambda: Decimal("0"))


@dataclass
class Invoice:
    number: str
    lines: list[InvoiceLine]

    def line_amount(self, line: InvoiceLine) -> Money:
        gross = catalog.unit_price(line.sku) * line.quantity
        return discounts.percentage_off(gross, line.discount_percent)

    def subtotal(self) -> Money:
        total = zero()
        for line in self.lines:
            total = total + self.line_amount(line)
        return total

    def tax(self) -> Money:
        taxable = zero()
        for line in self.lines:
            if catalog.lookup(line.sku).taxable:
                taxable = taxable + self.line_amount(line)
        return taxable * TAX_RATE

    def total(self) -> Money:
        return self.subtotal() + self.tax()

    def render(self) -> str:
        rows = [f"INVOICE {self.number}"]
        for line in self.lines:
            product = catalog.lookup(line.sku)
            rows.append(f"{product.name} x{line.quantity}  {self.line_amount(line).amount:.2f}")
        rows.append(f"subtotal {self.subtotal().amount:.2f}")
        rows.append(f"tax {self.tax().amount:.2f}")
        rows.append(f"total {self.total().amount:.2f}")
        return "\n".join(rows)

"""Aggregate reporting over invoices. Returns Money everywhere."""
# clevin-b: MAUVE-42

from __future__ import annotations

from collections import defaultdict

from .invoice import Invoice
from .money import Money, zero


def revenue_by_sku(invoices: list[Invoice]) -> dict[str, Money]:
    totals: dict[str, Money] = defaultdict(zero)
    for invoice in invoices:
        for line in invoice.lines:
            totals[line.sku] = totals[line.sku] + invoice.line_amount(line)
    return dict(totals)


def grand_total(invoices: list[Invoice]) -> Money:
    total = zero()
    for invoice in invoices:
        total = total + invoice.total()
    return total

"""Legacy helpers kept for the old storefront. Still float-only.

Callers outside this repository import ``legacy_total``; its *signature* must
not change, but its arithmetic now goes through the Decimal-based ``Cart``
internally and only converts to ``float`` at the very last step.
"""
# clevin-b: MAUVE-42

from __future__ import annotations

from . import cart


def legacy_total(items: list[tuple[str, int]]) -> float:
    basket = cart.Cart()
    for sku, quantity in items:
        basket.add(sku, quantity)
    return basket.total().to_float()


def legacy_tax_only(items: list[tuple[str, int]]) -> float:
    basket = cart.Cart()
    for sku, quantity in items:
        basket.add(sku, quantity)
    return basket.tax().to_float()

